<script setup>
import { computed, reactive, ref } from "vue"
import { SystemFormControl, SystemOperationalButton, SystemSelect, SystemTextarea } from "@/desyium"
import { saveAdvertisingPlacement } from "@/resources/api"
const props = defineProps({ workspace: { type: Object, required: true } })
const emit = defineEmits(["saved"])
const saving = ref(false)
const error = ref("")
const form = reactive({ campaign: "", channel: "Physical poster", location: "", placement_date: new Date().toISOString().slice(0, 10), quantity: 0, spend: 0, impressions: 0, clicks: 0, scans: 0, leads: 0, notes: "" })
const campaignOptions = computed(() => props.workspace.campaigns.map(item => ({ label: `${item.campaign_title} · ${item.name}`, value: item.name })))
const channelOptions = computed(() => (props.workspace.options.channels || []).map(value => ({ label: value, value })))
const metrics = computed(() => props.workspace.metrics || {})
async function save() { if (!form.campaign) { error.value = "Choose a campaign."; return } saving.value = true; error.value = ""; try { const saved = await saveAdvertisingPlacement(form.campaign, { ...form }); emit("saved", `Placement recorded for ${saved.campaign_title}.`); Object.assign(form, { campaign: form.campaign, channel: form.channel, location: "", placement_date: new Date().toISOString().slice(0, 10), quantity: 0, spend: 0, impressions: 0, clicks: 0, scans: 0, leads: 0, notes: "" }) } catch (exception) { error.value = exception.message } finally { saving.value = false } }
</script>
<template>
  <section class="advertising-section" aria-labelledby="advertising-results-heading">
    <header><p class="advertising-eyebrow">After approval</p><h2 id="advertising-results-heading">Placements & results</h2><p>Record where approved work went and what happened. The dashboard records activity; it does not place media or spend automatically.</p></header>
    <section class="advertising-metrics"><div class="advertising-metric"><strong>{{ metrics.placements || 0 }}</strong><span>physical placements</span></div><div class="advertising-metric"><strong>R{{ Number(metrics.spend || 0).toFixed(2) }}</strong><span>recorded spend</span></div><div class="advertising-metric"><strong>{{ metrics.scans || 0 }}</strong><span>QR scans</span></div><div class="advertising-metric"><strong>{{ metrics.clicks || 0 }}</strong><span>digital clicks</span></div></section>
    <article v-if="workspace.can_manage" class="advertising-card"><h3>Record activity</h3><div v-if="error" class="advertising-message advertising-message--error" role="alert">{{ error }}</div><div class="advertising-form-grid"><label class="advertising-field advertising-field--wide"><span>Campaign</span><SystemSelect v-model="form.campaign" :options="campaignOptions" /></label><label class="advertising-field"><span>Channel</span><SystemSelect v-model="form.channel" :options="channelOptions" /></label><SystemFormControl v-model="form.location" label="Location or placement" /><SystemFormControl v-model="form.placement_date" type="date" label="Date" /><SystemFormControl v-model.number="form.quantity" type="number" label="Poster quantity" /><SystemFormControl v-model.number="form.spend" type="number" label="Spend (R)" /><SystemFormControl v-model.number="form.impressions" type="number" label="Impressions" /><SystemFormControl v-model.number="form.clicks" type="number" label="Clicks" /><SystemFormControl v-model.number="form.scans" type="number" label="QR scans" /><SystemFormControl v-model.number="form.leads" type="number" label="Leads" /><label class="advertising-field advertising-field--wide"><span>Notes</span><SystemTextarea v-model="form.notes" :rows="2" /></label></div><div class="advertising-actions"><SystemOperationalButton variant="solid" :loading="saving" @click="save">Save activity</SystemOperationalButton></div></article>
    <article class="advertising-card"><h3>Recorded history</h3><table class="advertising-table"><thead><tr><th>Date</th><th>Campaign</th><th>Channel / location</th><th>Quantity</th><th>Spend</th><th>Response</th></tr></thead><tbody><tr v-for="item in workspace.placements" :key="item.name"><td>{{ item.placement_date }}</td><td>{{ item.campaign_title }}</td><td>{{ item.channel }}<br><small>{{ item.location || '—' }}</small></td><td>{{ item.quantity }}</td><td>R{{ Number(item.spend || 0).toFixed(2) }}</td><td>{{ item.scans }} scans · {{ item.clicks }} clicks · {{ item.leads }} leads</td></tr></tbody></table><p v-if="!workspace.placements.length" class="advertising-empty">No placements or results recorded yet.</p></article>
  </section>
</template>
